      "source": "PLoS ONE",
      "title": "Plastic Pollution in the World's Oceans: More than 5 Trillion Plastic Pieces Weighing over 250,000 Tons Afloat at Sea",
      "work_id": "doi:10.1371/journal.pone.0111913",
      "year": 2014
    }
